set-variable.value:
#[vars.outcomes ++ [
                            if (vars.res.status >= 400)
                              { row: vars.row.row, paymentRef: vars.row.paymentRef, invoiceNumber: vars.row.invoiceNumber, result: 'REJECTED', reason: vars.res.body.error.message default ('HTTP ' ++ (vars.res.status as String)) }
                            else
                              { row: vars.row.row, paymentRef: vars.row.paymentRef, invoiceNumber: vars.row.invoiceNumber, result: vars.res.body.result, invoiceStatus: vars.res.body.invoiceStatus }
                          ]]
